using System.Text.Json;

namespace VaiDrikstu.Domain.Assistant;

/// <summary>A searchable unit: exactly one of the three payloads is set.</summary>
public sealed record KnowledgeEntry(KnowledgeLabel? Label, KnowledgeDocument? Document, MonumentRecord? Monument)
{
    public string Kind => Label?.Kind ?? Document?.Kind ?? "monument";
}

/// <summary>
/// Read-only knowledge base generated by <c>tools/assistant-kb/build_knowledge_base.py</c>
/// from the project's open-data folders. Loaded once and shared.
/// </summary>
public sealed class KnowledgeBase
{
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    private readonly Dictionary<string, List<KnowledgeLabel>> _byCode = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<MonumentRecord>> _monumentsByCadastre = new(StringComparer.Ordinal);
    private readonly Dictionary<string, MonumentRecord> _monumentsByNr = new(StringComparer.Ordinal);

    public KnowledgeBase(
        IEnumerable<KnowledgeLabel> labels,
        IEnumerable<KnowledgeDocument> documents,
        IEnumerable<MonumentRecord> monuments,
        IReadOnlyDictionary<string, CadastreMarks> cadastreMarks)
    {
        Labels = labels.ToList();
        Documents = documents.ToList();
        Monuments = monuments.ToList();
        CadastreMarks = cadastreMarks;

        foreach (var label in Labels)
        {
            AddCode(label.Code, label);
            foreach (var alias in label.Aliases ?? [])
            {
                // Aliases that are codes (e.g. 'KODS', '7312050602') are looked up exactly;
                // name aliases of nature areas are searchable through the index instead.
                if (alias.Length <= 16 && !alias.Contains(' '))
                {
                    AddCode(alias, label);
                }
            }

            Index.Add(new KnowledgeEntry(label, null, null), LabelTerms(label));
        }

        foreach (var document in Documents)
        {
            var terms = TextAnalysis.Terms(document.Title);
            terms.AddRange(terms.ToList()); // title counts twice
            terms.AddRange(TextAnalysis.Terms(document.Text));
            Index.Add(new KnowledgeEntry(null, document, null), terms);
        }

        foreach (var monument in Monuments)
        {
            _monumentsByNr.TryAdd(monument.Nr, monument);
            foreach (var cadastre in monument.Cadastre)
            {
                if (!_monumentsByCadastre.TryGetValue(cadastre, out var list))
                {
                    list = [];
                    _monumentsByCadastre[cadastre] = list;
                }

                list.Add(monument);
            }

            var terms = TextAnalysis.Terms($"{monument.Name} {monument.Name} {monument.Location} {monument.Group} {monument.Value} piemineklis");
            Index.Add(new KnowledgeEntry(null, null, monument), terms);
        }
    }

    public IReadOnlyList<KnowledgeLabel> Labels { get; }

    public IReadOnlyList<KnowledgeDocument> Documents { get; }

    public IReadOnlyList<MonumentRecord> Monuments { get; }

    public IReadOnlyDictionary<string, CadastreMarks> CadastreMarks { get; }

    public SearchIndex<KnowledgeEntry> Index { get; } = new();

    public IReadOnlyList<KnowledgeLabel> FindByCode(string code) =>
        _byCode.TryGetValue(code, out var list) ? list : [];

    public KnowledgeLabel? Find(string kind, string code) =>
        FindByCode(code).FirstOrDefault(label => label.Kind == kind);

    public IReadOnlyList<MonumentRecord> MonumentsByCadastre(string cadastre)
    {
        if (_monumentsByCadastre.TryGetValue(cadastre, out var list))
        {
            return list;
        }

        // A building (14 digits) or parcel part may be listed under its land unit (11 digits).
        return cadastre.Length > 11 && _monumentsByCadastre.TryGetValue(cadastre[..11], out var parent) ? parent : [];
    }

    public MonumentRecord? MonumentByNumber(string nr) => _monumentsByNr.GetValueOrDefault(nr);

    public static KnowledgeBase Load(string directory)
    {
        var labels = ReadItems<List<KnowledgeLabel>>(Path.Combine(directory, "labels.json")) ?? [];
        var documents = ReadItems<List<KnowledgeDocument>>(Path.Combine(directory, "documents.json")) ?? [];
        var monuments = ReadItems<List<MonumentRecord>>(Path.Combine(directory, "monuments.json")) ?? [];
        var marks = ReadItems<Dictionary<string, CadastreMarks>>(Path.Combine(directory, "cadastre-marks.json")) ?? [];
        return new KnowledgeBase(labels, documents, monuments, marks);
    }

    private static T? ReadItems<T>(string path)
    {
        if (!File.Exists(path))
        {
            return default;
        }

        using var stream = File.OpenRead(path);
        using var document = JsonDocument.Parse(stream);
        return document.RootElement.TryGetProperty("items", out var items)
            ? items.Deserialize<T>(JsonOptions)
            : default;
    }

    private void AddCode(string code, KnowledgeLabel label)
    {
        if (!_byCode.TryGetValue(code, out var list))
        {
            list = [];
            _byCode[code] = list;
        }

        if (!list.Contains(label))
        {
            list.Add(label);
        }
    }

    private static List<string> LabelTerms(KnowledgeLabel label)
    {
        var terms = TextAnalysis.Terms($"{label.Code} {label.Title}");
        terms.AddRange(terms.ToList());
        terms.AddRange(TextAnalysis.Terms(label.Text));
        foreach (var translation in label.Translations?.Values ?? Enumerable.Empty<LabelTranslation>())
        {
            terms.AddRange(TextAnalysis.Terms($"{translation.Title} {translation.Text}"));
        }

        if (label.Meta is not null && label.Meta.TryGetValue("group", out var group) && group.ValueKind == JsonValueKind.String)
        {
            terms.AddRange(TextAnalysis.Terms(group.GetString() ?? string.Empty));
        }

        return terms;
    }
}
